-- SpazaStock shop Durable Object database: one SQLite database per shop, holding that shop's ledger.
-- Generated by `npm run data:schema` from supabase/migrations. Do not edit by hand before the
-- cutover: change the generator or partition.ts and regenerate. After cutover this file is frozen
-- and later changes go in new migrations.
-- Every row still carries shop_id, equal to the object's shop, so rows stay self-describing.

CREATE TABLE products (
  id TEXT NOT NULL,
  shop_id TEXT NOT NULL,
  barcode TEXT NOT NULL,
  name TEXT NOT NULL,
  category TEXT NOT NULL DEFAULT 'other',
  buying_price_cents INTEGER,
  selling_price_cents INTEGER,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  archived_at TEXT,
  brand TEXT,
  size TEXT,
  image_path TEXT,
  min_stock_units INTEGER,
  catalog_product_id TEXT,
  listed INTEGER NOT NULL DEFAULT 1 CHECK (listed IN (0, 1)),
  target_stock_units INTEGER,
  PRIMARY KEY (id),
  CHECK (((length(barcode) >= 1) AND (length(barcode) <= 64))),
  CHECK (((brand IS NULL) OR ((length(trim(brand)) >= 1) AND (length(trim(brand)) <= 80)))),
  CHECK ((buying_price_cents >= (0))),
  CHECK ((category IN ('groceries', 'beverages', 'snacks', 'bakery', 'dairy', 'personal_care', 'household', 'airtime', 'other'))),
  CHECK ((min_stock_units >= 0)),
  CHECK (((length(trim(name)) >= 1) AND (length(trim(name)) <= 200))),
  CHECK ((selling_price_cents >= (0))),
  CHECK (((size IS NULL) OR ((length(trim(size)) >= 1) AND (length(trim(size)) <= 40)))),
  CHECK ((target_stock_units >= 0))
) STRICT;
CREATE INDEX products_catalog_shop_idx ON products (catalog_product_id, shop_id) WHERE (catalog_product_id IS NOT NULL);
CREATE INDEX products_image_path_idx ON products (image_path) WHERE (image_path IS NOT NULL);
CREATE UNIQUE INDEX products_shop_barcode_key ON products (shop_id, barcode);
CREATE UNIQUE INDEX products_shop_catalog_active_key ON products (shop_id, catalog_product_id) WHERE ((catalog_product_id IS NOT NULL) AND (archived_at IS NULL));
CREATE UNIQUE INDEX products_shop_id_id_key ON products (shop_id, id);
CREATE INDEX products_shop_updated_idx ON products (shop_id, updated_at);

CREATE TABLE sales (
  id TEXT NOT NULL,
  shop_id TEXT NOT NULL,
  total_amount_cents INTEGER NOT NULL,
  idempotency_key TEXT NOT NULL,
  sold_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  item_count INTEGER NOT NULL,
  sold_by TEXT,
  PRIMARY KEY (id),
  CHECK ((item_count > 0)),
  CHECK ((total_amount_cents >= (0)))
) STRICT;
CREATE INDEX sales_created_at_idx ON sales (created_at);
CREATE UNIQUE INDEX sales_shop_id_id_key ON sales (shop_id, id);
CREATE UNIQUE INDEX sales_shop_idempotency_key ON sales (shop_id, idempotency_key);
CREATE INDEX sales_shop_sold_at_idx ON sales (shop_id, sold_at DESC);
CREATE INDEX sales_shop_updated_idx ON sales (shop_id, updated_at);
CREATE INDEX sales_sold_by_idx ON sales (sold_by);

CREATE TABLE wholesalers (
  id TEXT NOT NULL,
  shop_id TEXT NOT NULL,
  name TEXT NOT NULL,
  phone TEXT,
  note TEXT,
  archived_at TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  PRIMARY KEY (id),
  CHECK (((length(trim(name)) >= 1) AND (length(trim(name)) <= 80))),
  CHECK (((note IS NULL) OR (length(note) <= 280))),
  CHECK (((phone IS NULL) OR ((length(phone) >= 1) AND (length(phone) <= 40))))
) STRICT;
CREATE UNIQUE INDEX wholesalers_active_name_idx ON wholesalers (shop_id, lower(name)) WHERE (archived_at IS NULL);
CREATE UNIQUE INDEX wholesalers_shop_id_key ON wholesalers (shop_id, id);
CREATE INDEX wholesalers_shop_updated_idx ON wholesalers (shop_id, updated_at);

CREATE TABLE low_stock_episodes (
  shop_id TEXT NOT NULL,
  product_id TEXT NOT NULL,
  PRIMARY KEY (shop_id, product_id),
  FOREIGN KEY (shop_id, product_id) REFERENCES products (shop_id, id) ON DELETE CASCADE
) STRICT;

CREATE TABLE low_stock_dismissals (
  id TEXT NOT NULL,
  shop_id TEXT NOT NULL,
  product_id TEXT NOT NULL,
  dismissed_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  dismissed_by TEXT,
  cleared_at TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  PRIMARY KEY (id),
  FOREIGN KEY (shop_id, product_id) REFERENCES products (shop_id, id) ON DELETE CASCADE
) STRICT;
CREATE UNIQUE INDEX low_stock_dismissals_shop_product_key ON low_stock_dismissals (shop_id, product_id);
CREATE INDEX low_stock_dismissals_shop_updated_idx ON low_stock_dismissals (shop_id, updated_at);

CREATE TABLE product_packagings (
  id TEXT NOT NULL,
  shop_id TEXT NOT NULL,
  product_id TEXT NOT NULL,
  name TEXT NOT NULL,
  units_per_package INTEGER NOT NULL,
  created_by TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  retired_at TEXT,
  selling_price_cents INTEGER,
  PRIMARY KEY (id),
  FOREIGN KEY (shop_id, product_id) REFERENCES products (shop_id, id) ON DELETE CASCADE,
  CHECK (((length(trim(name)) >= 1) AND (length(trim(name)) <= 40))),
  CHECK (((selling_price_cents IS NULL) OR (selling_price_cents >= (0)))),
  CHECK (((units_per_package >= 2) AND (units_per_package <= 10000)))
) STRICT;
CREATE INDEX product_packagings_created_by_idx ON product_packagings (created_by);
CREATE UNIQUE INDEX product_packagings_shop_product_id_key ON product_packagings (shop_id, product_id, id);
CREATE INDEX product_packagings_shop_product_idx ON product_packagings (shop_id, product_id);
CREATE INDEX product_packagings_shop_updated_idx ON product_packagings (shop_id, updated_at);

CREATE TABLE sale_items (
  id TEXT NOT NULL,
  shop_id TEXT NOT NULL,
  sale_id TEXT NOT NULL,
  product_id TEXT NOT NULL,
  quantity INTEGER NOT NULL,
  unit_price_cents INTEGER NOT NULL DEFAULT 0,
  line_total_cents INTEGER NOT NULL,
  allocations TEXT NOT NULL DEFAULT '[]',
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  voided_quantity INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY (id),
  FOREIGN KEY (shop_id, product_id) REFERENCES products (shop_id, id) ON DELETE CASCADE,
  FOREIGN KEY (shop_id, sale_id) REFERENCES sales (shop_id, id) ON DELETE CASCADE,
  CHECK ((line_total_cents >= (0))),
  CHECK ((quantity > 0)),
  CHECK ((unit_price_cents >= (0))),
  CHECK (((voided_quantity >= 0) AND (voided_quantity <= quantity)))
) STRICT;
CREATE INDEX sale_items_shop_product_idx ON sale_items (shop_id, product_id);
CREATE INDEX sale_items_shop_sale_idx ON sale_items (shop_id, sale_id);
CREATE INDEX sale_items_shop_updated_idx ON sale_items (shop_id, updated_at);

CREATE TABLE wholesale_orders (
  id TEXT NOT NULL,
  shop_id TEXT NOT NULL,
  wholesaler_id TEXT,
  status TEXT NOT NULL DEFAULT 'draft',
  note TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  PRIMARY KEY (id),
  FOREIGN KEY (shop_id, wholesaler_id) REFERENCES wholesalers (shop_id, id),
  CHECK (((note IS NULL) OR (length(note) <= 280))),
  CHECK ((status IN ('draft', 'approved', 'ordered', 'partially_received', 'received', 'cancelled')))
) STRICT;
CREATE UNIQUE INDEX wholesale_orders_shop_id_key ON wholesale_orders (shop_id, id);
CREATE INDEX wholesale_orders_shop_updated_idx ON wholesale_orders (shop_id, updated_at);

CREATE TABLE product_barcodes (
  id TEXT NOT NULL,
  shop_id TEXT NOT NULL,
  product_id TEXT NOT NULL,
  packaging_id TEXT,
  barcode TEXT NOT NULL,
  created_by TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  unlinked_at TEXT,
  unlinked_by TEXT,
  unlink_reason TEXT,
  PRIMARY KEY (id),
  FOREIGN KEY (shop_id, product_id, packaging_id) REFERENCES product_packagings (shop_id, product_id, id),
  FOREIGN KEY (shop_id, product_id) REFERENCES products (shop_id, id) ON DELETE CASCADE,
  CHECK (((unlinked_at IS NULL) = (unlink_reason IS NULL))),
  CHECK (((unlink_reason IS NULL) OR ((length(trim(unlink_reason)) >= 1) AND (length(trim(unlink_reason)) <= 200))))
) STRICT;
CREATE UNIQUE INDEX product_barcodes_active_key ON product_barcodes (shop_id, barcode) WHERE (unlinked_at IS NULL);
CREATE INDEX product_barcodes_created_by_idx ON product_barcodes (created_by);
CREATE INDEX product_barcodes_packaging_idx ON product_barcodes (shop_id, product_id, packaging_id);
CREATE INDEX product_barcodes_shop_updated_idx ON product_barcodes (shop_id, updated_at);
CREATE INDEX product_barcodes_unlinked_by_idx ON product_barcodes (unlinked_by);

CREATE TABLE sale_item_voids (
  id TEXT NOT NULL,
  shop_id TEXT NOT NULL,
  sale_id TEXT NOT NULL,
  sale_item_id TEXT NOT NULL,
  quantity INTEGER NOT NULL,
  idempotency_key TEXT NOT NULL,
  voided_by TEXT,
  occurred_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  PRIMARY KEY (id),
  FOREIGN KEY (shop_id, sale_id) REFERENCES sales (shop_id, id) ON DELETE CASCADE,
  FOREIGN KEY (sale_item_id) REFERENCES sale_items (id) ON DELETE CASCADE,
  CHECK (((length(idempotency_key) >= 1) AND (length(idempotency_key) <= 200))),
  CHECK ((quantity > 0))
) STRICT;
CREATE INDEX sale_item_voids_sale_item_id_idx ON sale_item_voids (sale_item_id);
CREATE INDEX sale_item_voids_shop_created_idx ON sale_item_voids (shop_id, created_at);
CREATE UNIQUE INDEX sale_item_voids_shop_idempotency_key ON sale_item_voids (shop_id, idempotency_key);
CREATE INDEX sale_item_voids_shop_sale_idx ON sale_item_voids (shop_id, sale_id);
CREATE INDEX sale_item_voids_voided_by_idx ON sale_item_voids (voided_by);

CREATE TABLE stock_discrepancies (
  id TEXT NOT NULL,
  shop_id TEXT NOT NULL,
  product_id TEXT NOT NULL,
  sale_id TEXT,
  shortfall INTEGER NOT NULL,
  resolved_at TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  sale_item_id TEXT,
  PRIMARY KEY (id),
  FOREIGN KEY (shop_id, product_id) REFERENCES products (shop_id, id) ON DELETE CASCADE,
  FOREIGN KEY (sale_id) REFERENCES sales (id) ON DELETE SET NULL,
  FOREIGN KEY (sale_item_id) REFERENCES sale_items (id) ON DELETE SET NULL,
  CHECK ((shortfall > 0))
) STRICT;
CREATE INDEX stock_discrepancies_sale_id_idx ON stock_discrepancies (sale_id);
CREATE INDEX stock_discrepancies_sale_item_id_idx ON stock_discrepancies (sale_item_id);
CREATE INDEX stock_discrepancies_shop_product_idx ON stock_discrepancies (shop_id, product_id);
CREATE INDEX stock_discrepancies_shop_updated_idx ON stock_discrepancies (shop_id, updated_at);

CREATE TABLE wholesale_order_items (
  id TEXT NOT NULL,
  shop_id TEXT NOT NULL,
  order_id TEXT NOT NULL,
  product_id TEXT NOT NULL,
  quantity INTEGER NOT NULL,
  removed_at TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  estimated_unit_cost_cents INTEGER,
  purchased_at TEXT,
  PRIMARY KEY (id),
  FOREIGN KEY (shop_id, order_id) REFERENCES wholesale_orders (shop_id, id) ON DELETE CASCADE,
  FOREIGN KEY (shop_id, product_id) REFERENCES products (shop_id, id),
  CHECK (((estimated_unit_cost_cents IS NULL) OR (estimated_unit_cost_cents >= (0)))),
  CHECK (((quantity >= 1) AND (quantity <= 1000000)))
) STRICT;
CREATE UNIQUE INDEX wholesale_order_items_active_product_idx ON wholesale_order_items (order_id, product_id) WHERE (removed_at IS NULL);
CREATE INDEX wholesale_order_items_shop_updated_idx ON wholesale_order_items (shop_id, updated_at);

CREATE TABLE wholesale_order_receipts (
  id TEXT NOT NULL,
  shop_id TEXT NOT NULL,
  order_id TEXT NOT NULL,
  received_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  received_by TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  PRIMARY KEY (id),
  FOREIGN KEY (shop_id, order_id) REFERENCES wholesale_orders (shop_id, id) ON DELETE CASCADE
) STRICT;
CREATE UNIQUE INDEX wholesale_order_receipts_shop_id_key ON wholesale_order_receipts (shop_id, id);
CREATE INDEX wholesale_order_receipts_shop_updated_idx ON wholesale_order_receipts (shop_id, updated_at);

CREATE TABLE stock_batches (
  id TEXT NOT NULL,
  shop_id TEXT NOT NULL,
  product_id TEXT NOT NULL,
  quantity INTEGER NOT NULL,
  initial_quantity INTEGER NOT NULL,
  expiry_date TEXT,
  cost_price_per_unit_cents INTEGER,
  received_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  received_by TEXT,
  packaging_id TEXT,
  package_quantity INTEGER,
  units_per_package INTEGER,
  received_barcode_id TEXT,
  lot_number TEXT,
  supplier_name TEXT,
  PRIMARY KEY (id),
  FOREIGN KEY (shop_id, product_id, packaging_id) REFERENCES product_packagings (shop_id, product_id, id),
  FOREIGN KEY (shop_id, product_id) REFERENCES products (shop_id, id) ON DELETE CASCADE,
  FOREIGN KEY (received_barcode_id) REFERENCES product_barcodes (id) ON DELETE SET NULL,
  CHECK ((cost_price_per_unit_cents >= (0))),
  CHECK ((initial_quantity > 0)),
  CHECK (((lot_number IS NULL) OR ((length(trim(lot_number)) >= 1) AND (length(trim(lot_number)) <= 40)))),
  CHECK ((((packaging_id IS NULL) AND (package_quantity IS NULL) AND (units_per_package IS NULL)) OR ((packaging_id IS NOT NULL) AND (package_quantity > 0) AND (units_per_package >= 2) AND (initial_quantity = (package_quantity * units_per_package))))),
  CHECK ((quantity >= 0)),
  CHECK (((supplier_name IS NULL) OR ((length(trim(supplier_name)) >= 1) AND (length(trim(supplier_name)) <= 80))))
) STRICT;
CREATE INDEX stock_batches_expiry_idx ON stock_batches (expiry_date) WHERE ((quantity > 0) AND (expiry_date IS NOT NULL));
CREATE INDEX stock_batches_fefo_idx ON stock_batches (shop_id, product_id, expiry_date, received_at) WHERE (quantity > 0);
CREATE INDEX stock_batches_packaging_idx ON stock_batches (shop_id, product_id, packaging_id);
CREATE INDEX stock_batches_product_id_idx ON stock_batches (product_id);
CREATE INDEX stock_batches_received_barcode_idx ON stock_batches (received_barcode_id);
CREATE INDEX stock_batches_received_by_idx ON stock_batches (received_by);
CREATE INDEX stock_batches_shop_updated_idx ON stock_batches (shop_id, updated_at);

CREATE TABLE wholesale_order_receipt_lines (
  id TEXT NOT NULL,
  shop_id TEXT NOT NULL,
  receipt_id TEXT NOT NULL,
  order_item_id TEXT NOT NULL,
  batch_id TEXT NOT NULL,
  quantity INTEGER NOT NULL,
  expiry_date TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  PRIMARY KEY (id),
  FOREIGN KEY (order_item_id) REFERENCES wholesale_order_items (id),
  FOREIGN KEY (shop_id, receipt_id) REFERENCES wholesale_order_receipts (shop_id, id) ON DELETE CASCADE,
  CHECK (((quantity >= 1) AND (quantity <= 1000000)))
) STRICT;
CREATE UNIQUE INDEX wholesale_order_receipt_lines_batch_id_key ON wholesale_order_receipt_lines (batch_id);
CREATE INDEX wholesale_order_receipt_lines_item_idx ON wholesale_order_receipt_lines (order_item_id);
CREATE INDEX wholesale_order_receipt_lines_shop_updated_idx ON wholesale_order_receipt_lines (shop_id, updated_at);

CREATE TABLE expiry_alerts (
  id TEXT NOT NULL,
  shop_id TEXT NOT NULL,
  batch_id TEXT NOT NULL,
  product_id TEXT NOT NULL,
  kind TEXT NOT NULL,
  threshold_days INTEGER,
  expiry_date TEXT NOT NULL,
  quantity INTEGER NOT NULL,
  alert_date TEXT NOT NULL,
  resolved_at TEXT,
  resolution TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  PRIMARY KEY (id),
  FOREIGN KEY (batch_id) REFERENCES stock_batches (id) ON DELETE CASCADE,
  FOREIGN KEY (shop_id, product_id) REFERENCES products (shop_id, id) ON DELETE CASCADE,
  CHECK ((kind IN ('reminder', 'expired'))),
  CHECK ((quantity >= 0)),
  CHECK (((resolution IS NULL) OR (resolution IN ('sold_out', 'discarded', 'returned_to_supplier', 'expiry_corrected', 'superseded', 'product_archived')))),
  CHECK (((resolved_at IS NULL) = (resolution IS NULL))),
  CHECK (((kind = 'reminder') = (threshold_days IS NOT NULL))),
  CHECK (((threshold_days IS NULL) OR ((threshold_days >= 1) AND (threshold_days <= 180))))
) STRICT;
CREATE INDEX expiry_alerts_created_at_idx ON expiry_alerts (created_at);
CREATE UNIQUE INDEX expiry_alerts_dedup_key ON expiry_alerts (batch_id, expiry_date, kind, ifnull(threshold_days, x'00'));
CREATE INDEX expiry_alerts_open_idx ON expiry_alerts (shop_id) WHERE (resolved_at IS NULL);
CREATE INDEX expiry_alerts_shop_product_idx ON expiry_alerts (shop_id, product_id);
CREATE INDEX expiry_alerts_shop_updated_idx ON expiry_alerts (shop_id, updated_at);

CREATE TABLE stock_movements (
  id TEXT NOT NULL,
  shop_id TEXT NOT NULL,
  product_id TEXT NOT NULL,
  batch_id TEXT,
  sale_id TEXT,
  quantity_delta INTEGER NOT NULL,
  resulting_total_quantity INTEGER NOT NULL,
  idempotency_key TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  reason TEXT NOT NULL,
  actor_id TEXT,
  occurred_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  sale_item_id TEXT,
  PRIMARY KEY (id),
  FOREIGN KEY (batch_id) REFERENCES stock_batches (id) ON DELETE SET NULL,
  FOREIGN KEY (shop_id, product_id) REFERENCES products (shop_id, id) ON DELETE CASCADE,
  FOREIGN KEY (sale_id) REFERENCES sales (id) ON DELETE SET NULL,
  FOREIGN KEY (sale_item_id) REFERENCES sale_items (id) ON DELETE SET NULL,
  CHECK (((length(idempotency_key) >= 1) AND (length(idempotency_key) <= 400))),
  CHECK ((quantity_delta <> 0)),
  CHECK ((reason IN ('stock_in', 'sale', 'adjustment', 'write_off_expired', 'write_off_damaged', 'count_correction', 'return', 'supplier_return')))
) STRICT;
CREATE INDEX stock_movements_actor_id_idx ON stock_movements (actor_id);
CREATE INDEX stock_movements_batch_id_idx ON stock_movements (batch_id);
CREATE INDEX stock_movements_created_at_idx ON stock_movements (created_at);
CREATE INDEX stock_movements_sale_id_idx ON stock_movements (sale_id);
CREATE INDEX stock_movements_sale_item_id_idx ON stock_movements (sale_item_id);
CREATE INDEX stock_movements_shop_created_idx ON stock_movements (shop_id, created_at DESC);
CREATE UNIQUE INDEX stock_movements_shop_idempotency_key ON stock_movements (shop_id, idempotency_key);
CREATE INDEX stock_movements_shop_product_idx ON stock_movements (shop_id, product_id);
CREATE INDEX stock_movements_shop_updated_idx ON stock_movements (shop_id, updated_at);

CREATE TABLE expiry_resolutions (
  id TEXT NOT NULL,
  shop_id TEXT NOT NULL,
  batch_id TEXT NOT NULL,
  product_id TEXT NOT NULL,
  action TEXT NOT NULL,
  quantity INTEGER NOT NULL,
  previous_expiry_date TEXT,
  new_expiry_date TEXT,
  note TEXT,
  movement_id TEXT,
  idempotency_key TEXT NOT NULL,
  resolved_by TEXT,
  occurred_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  PRIMARY KEY (id),
  FOREIGN KEY (batch_id) REFERENCES stock_batches (id) ON DELETE CASCADE,
  FOREIGN KEY (movement_id) REFERENCES stock_movements (id) ON DELETE SET NULL,
  FOREIGN KEY (shop_id, product_id) REFERENCES products (shop_id, id) ON DELETE CASCADE,
  CHECK ((action IN ('discarded', 'returned_to_supplier', 'expiry_corrected'))),
  CHECK (((length(idempotency_key) >= 1) AND (length(idempotency_key) <= 200))),
  CHECK (((note IS NULL) OR (length(note) <= 500))),
  CHECK ((quantity >= 0))
) STRICT;
CREATE INDEX expiry_resolutions_batch_id_idx ON expiry_resolutions (batch_id);
CREATE INDEX expiry_resolutions_movement_id_idx ON expiry_resolutions (movement_id);
CREATE INDEX expiry_resolutions_resolved_by_idx ON expiry_resolutions (resolved_by);
CREATE INDEX expiry_resolutions_shop_created_idx ON expiry_resolutions (shop_id, created_at);
CREATE UNIQUE INDEX expiry_resolutions_shop_idempotency_key ON expiry_resolutions (shop_id, idempotency_key);
CREATE INDEX expiry_resolutions_shop_product_idx ON expiry_resolutions (shop_id, product_id);

-- Not expressible in SQLite. The Worker must enforce these rules:
--   products [foreign_key] (catalog_product_id) → catalog_products(id) (target lives in D1)
--   products [foreign_key] (shop_id) → shops(id) (target lives in D1)
--   products [check] CHECK (((image_path IS NULL) OR (image_path ~ (('^'::text || (shop_id)::text) || '/[0-9a-f]{32}\.(webp|jpg)$'::text)) OR (image_path ~ '^catalog/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\.(webp|jpg)$'::text))) (uses a regex or a database function)
--   sales [default] sold_by DEFAULT auth.uid() (supplied by the Worker)
--   sales [foreign_key] (shop_id) → shops(id) (target lives in D1)
--   sales [foreign_key] (sold_by) → users(id) (target lives in D1)
--   wholesalers [foreign_key] (shop_id) → shops(id) (target lives in D1)
--   low_stock_dismissals [default] id DEFAULT gen_random_uuid() (supplied by the Worker)
--   low_stock_dismissals [default] dismissed_by DEFAULT auth.uid() (supplied by the Worker)
--   low_stock_dismissals [foreign_key] (dismissed_by) → users(id) (target lives in D1)
--   low_stock_dismissals [foreign_key] (shop_id) → shops(id) (target lives in D1)
--   product_packagings [default] created_by DEFAULT auth.uid() (supplied by the Worker)
